const $=id=>document.getElementById(id), fields=['nome','org','area','url','prazo','valor','elegibilidade','criterios','notas','proposta'];let rows=[],diagnostic='';
function toast(s){$('toast').textContent=s}
function tab(n){$('edital').hidden=n!==1;$('revisao').hidden=n!==2;$('tab1').setAttribute('aria-selected',n===1);$('tab2').setAttribute('aria-selected',n===2)}
$('tab1').onclick=()=>tab(1);$('tab2').onclick=()=>tab(2);$('next').onclick=()=>{tab(2);build()};$('form').onsubmit=e=>e.preventDefault();
function data(){return Object.fromEntries(fields.map(k=>[k,$(k).value]))}
function fill(d){fields.forEach(k=>{if(d[k]!==undefined)$(k).value=d[k]});rows=[];diagnostic='';$('checklist').replaceChildren();$('resultado').replaceChildren();$('report').hidden=true}
$('demo').onclick=()=>{fill({nome:'EXEMPLO FICTÍCIO — Vozes do território',org:'Organização demonstrativa (não existe)',area:'Comunicação comunitária',url:'',prazo:'',valor:'Exemplo: até R$ 20 mil; confirmar condições',elegibilidade:'Exemplo fictício: coletivos de comunicação locais. Não corresponde a edital real.',criterios:'Descrever público e território atendidos\nApresentar cronograma de execução\nDetalhar orçamento por atividade\nDemonstrar experiência da equipe\nPrever acessibilidade das entregas',notas:'Exemplo pedagógico, não é oportunidade aberta.',proposta:'Produziremos uma série de reportagens sobre os desafios de mobilidade do bairro, ouvindo moradores e associações locais. A entrega será publicada em nosso site e distribuída por WhatsApp.'});toast('Exemplo fictício carregado. Nenhum edital real ou prazo vigente está sendo anunciado.')};
function build(){const cs=$('criterios').value.split('\n').map(x=>x.trim()).filter(Boolean);$('checklist').replaceChildren();rows=[];diagnostic='';$('resultado').replaceChildren();if(!cs.length){toast('Preencha pelo menos um critério no módulo 01.');return}cs.forEach((c,i)=>{const card=document.createElement('div');card.className='card';const title=document.createElement('h3');title.textContent=(i+1)+'. '+c;const lab=document.createElement('label');lab.textContent='Sua avaliação';const sel=document.createElement('select');['Não verificado','Atendido com evidência','Parcialmente atendido','Ausente / precisa corrigir','Não se aplica (justifique)'].forEach(t=>{const op=document.createElement('option');op.textContent=t;sel.append(op)});sel.setAttribute('aria-label','Situação do critério '+(i+1));const note=document.createElement('textarea');note.placeholder='Cole o trecho que comprova ou registre o ajuste necessário';note.setAttribute('aria-label','Evidência do critério '+(i+1));card.append(title,lab,sel,note);$('checklist').append(card);rows.push({c,sel,note})});$('report').hidden=false;toast('Checklist montado. Marque cada requisito e registre a evidência. Remontar descarta as marcações atuais.')}
$('build').onclick=build;
$('report').onclick=()=>{if(!rows.length)return;const sections={'Pontos fortes documentados':[],'Ajustes prioritários':[],'Ainda precisa verificar':[]};rows.forEach(({c,sel,note})=>{let s=sel.value,e=note.value.trim();if(s==='Atendido com evidência'&&e)sections['Pontos fortes documentados'].push(c+' — '+e);else if(s==='Parcialmente atendido'||s==='Ausente / precisa corrigir')sections['Ajustes prioritários'].push(c+' — '+(e||'Descreva uma entrega concreta e inclua a evidência correspondente.'));else sections['Ainda precisa verificar'].push(c+' — '+(s==='Atendido com evidência'?'Você marcou como atendido, mas não registrou a evidência.':s==='Não se aplica (justifique)'?(e?'Justificativa registrada: '+e+'. Confirme na fonte se a exceção é permitida.':'Justifique a dispensa e confirme na fonte.'):'Confira o edital e registre evidência.'))});$('resultado').replaceChildren();diagnostic='REVISÃO POR CHECKLIST — NÃO É ANÁLISE AUTOMÁTICA POR IA\n';for(const [h,items] of Object.entries(sections)){const card=document.createElement('div');card.className='card';const heading=document.createElement('h3');heading.textContent=h;card.append(heading);items.forEach(t=>{const p=document.createElement('p');p.textContent=t;card.append(p)});if(!items.length){const p=document.createElement('p');p.textContent='Nenhum item nesta categoria.';card.append(p)}$('resultado').append(card);diagnostic+='\n'+h+'\n'+items.join('\n')+'\n'}const p=document.createElement('p');p.className='notice';p.textContent='Antes de enviar: confira a versão oficial, o prazo, a elegibilidade, os anexos e a correspondência entre orçamento e cronograma. Este diagnóstico reflete sua avaliação, não valida a veracidade das evidências.';$('resultado').append(p)};
$('save').onclick=()=>{try{localStorage.setItem('codesinfo-grants-v1',JSON.stringify(data()));toast('Ficha e proposta salvas neste navegador. Marcações do checklist não são salvas; exporte o diagnóstico.')}catch{toast('Não foi possível salvar. Use a exportação.')}};
$('clear').onclick=()=>{if(confirm('Apagar ficha, proposta e dados salvos neste navegador?')){localStorage.removeItem('codesinfo-grants-v1');fill(Object.fromEntries(fields.map(k=>[k,k==='area'?'Jornalismo':''])));toast('Dados removidos deste navegador.')}};
$('export').onclick=()=>{const d=data(),t=Object.entries(d).map(([k,v])=>k.toUpperCase()+':\n'+v).join('\n\n')+'\n\n'+diagnostic;const u=URL.createObjectURL(new Blob([t],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download='ficha-e-revisao.txt';a.click();URL.revokeObjectURL(u);toast('Arquivo preparado. O diagnóstico só é incluído se você o gerar antes.')};
try{const saved=localStorage.getItem('codesinfo-grants-v1');if(saved){fill(JSON.parse(saved));toast('Ficha recuperada deste navegador.')}}catch{}
